import{_ as e,o as a,c as r,a4 as l}from"./chunks/framework.9tZL7ZIQ.js";const b=JSON.parse('{"title":"Forest River（森林河）","description":"","frontmatter":{},"headers":[],"relativePath":"03_companies/Forest River.md","filePath":"03_companies/Forest River.md"}'),i={name:"03_companies/Forest River.md"};function o(h,t,d,s,n,c){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="forest-river-森林河" tabindex="-1">Forest River（森林河） <a class="header-anchor" href="#forest-river-森林河" aria-label="Permalink to &quot;Forest River（森林河）&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>内容</th></tr></thead><tbody><tr><td>英文名</td><td>Forest River Inc.</td></tr><tr><td>行业</td><td>休闲车辆（RV）与游艇制造</td></tr><tr><td>成立年份</td><td>1990年代</td></tr><tr><td>创始人</td><td>Pete Liegl（皮特·利格尔）</td></tr><tr><td>总部</td><td>印第安纳州埃尔克哈特</td></tr><tr><td>伯克希尔持股</td><td>100%</td></tr><tr><td>收购年份</td><td>2005年</td></tr><tr><td>收购价格</td><td>约8亿美元</td></tr></tbody></table><h2 id="核心业务" tabindex="-1">核心业务 <a class="header-anchor" href="#核心业务" aria-label="Permalink to &quot;核心业务&quot;">​</a></h2><p>Forest River 是美国最大的休闲车辆（RV）制造商之一，产品涵盖：</p><ul><li><strong>房车（RV）</strong>：包括自行式房车和拖挂式房车</li><li><strong>游艇</strong>：私人游艇制造</li><li><strong>货运拖车</strong>：商用货运拖车</li><li><strong>巴士</strong>：商用巴士车辆</li></ul><p>总部位于印第安纳州埃尔克哈特——美国RV制造业的核心聚集区。</p><h2 id="收购故事" tabindex="-1">收购故事 <a class="header-anchor" href="#收购故事" aria-label="Permalink to &quot;收购故事&quot;">​</a></h2><h3 id="收购背景" tabindex="-1">收购背景 <a class="header-anchor" href="#收购背景" aria-label="Permalink to &quot;收购背景&quot;">​</a></h3><ul><li><strong>2005年</strong>：<a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a>以约8亿美元收购 Forest River 100% 股权</li><li>收购时 Forest River 已是美国领先的 RV 制造商之一</li><li>这笔收购是巴菲特早期对制造业公司的重要布局之一</li></ul><h3 id="收购逻辑" tabindex="-1">收购逻辑 <a class="header-anchor" href="#收购逻辑" aria-label="Permalink to &quot;收购逻辑&quot;">​</a></h3><ol><li><strong>行业地位稳固</strong>：美国最大 RV 制造商之一，市场份额领先</li><li><strong>创始人持续经营</strong>：收购后创始人 <a href="/04_people/皮特·利格尔.html">皮特·利格尔</a> 继续担任 CEO，保持管理稳定性</li><li><strong>产品线多元</strong>：房车、游艇、拖车等多品类分散风险</li><li><strong>消费升级趋势</strong>：美国老龄化及退休人群对 RV 旅游需求持续增长</li></ol><h2 id="管理团队" tabindex="-1">管理团队 <a class="header-anchor" href="#管理团队" aria-label="Permalink to &quot;管理团队&quot;">​</a></h2><h3 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h3><table tabindex="0"><thead><tr><th>姓名</th><th>职位</th><th>贡献</th></tr></thead><tbody><tr><td><a href="/04_people/皮特·利格尔.html">皮特·利格尔</a>（Pete Liegl）</td><td>创始人兼 CEO</td><td>1990年代创立公司，2005年后继续执掌</td></tr></tbody></table><h3 id="管理特点" tabindex="-1">管理特点 <a class="header-anchor" href="#管理特点" aria-label="Permalink to &quot;管理特点&quot;">​</a></h3><ul><li>创始人文化延续，管理层稳定</li><li>保持产品创新与品质标准</li><li>与伯克希尔的充分授权模式契合</li></ul><h2 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h2><blockquote><p>&quot;Forest River 是我们制造业板块的重要拼图，皮特·利格尔是出色的管理者。&quot; —— 2005年股东信</p></blockquote><blockquote><p>&quot;我们喜欢收购由优秀人才管理的优秀企业，Forest River 两者兼具。&quot; —— 2007年股东信</p></blockquote><h2 id="财务表现-摘录" tabindex="-1">财务表现（摘录） <a class="header-anchor" href="#财务表现-摘录" aria-label="Permalink to &quot;财务表现（摘录）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>备注</th></tr></thead><tbody><tr><td>2005（收购年）</td><td>伯克希尔以约8亿美元收购</td></tr><tr><td>收购后</td><td>持续贡献利润，保持行业领先地位</td></tr></tbody></table><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><p>2005, 2006, 2007, 2008, 2009, 2010</p><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/03_companies/伯克希尔哈撒韦.html">伯克希尔哈撒韦</a> - 母公司</li><li><a href="/04_people/皮特·利格尔.html">皮特·利格尔</a> - 创始人兼 CEO</li><li><a href="/03_companies/喜诗糖果.html">喜诗糖果</a> - 同为经典收购案例</li><li><a href="/03_companies/内布拉斯加家具城.html">内布拉斯加家具城</a> - 同为经典收购案例</li></ul><hr><p><em>最后更新：2026-04-12</em></p><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/01_letters/2005年/翻译.html">/01_letters/2005年/翻译</a></li><li><a href="/01_letters/2006年/翻译.html">/01_letters/2006年/翻译</a></li><li><a href="/01_letters/2017年/翻译.html">/01_letters/2017年/翻译</a></li><li><a href="/01_letters/1988年/翻译.html">/01_letters/1988年/翻译</a></li></ul>',31)])])}const m=e(i,[["render",o]]);export{b as __pageData,m as default};
